// Find glyph data by Unicode code point (binary search, PROGMEM-safe)
inline const uint8_t* findGB2312Glyph(uint16_t unicode) {
  int lo = 0, hi = 4437 - 1;
  while (lo <= hi) {
    int mid = (lo + hi) / 2;
    uint16_t u = pgm_read_word(&gb2312_map[mid].unicode);
    if (u == unicode) {
      uint16_t idx = pgm_read_word(&gb2312_map[mid].idx);
      return &gb2312_glyph_data[idx * 32];
    }
    if (u < unicode) lo = mid + 1;
    else hi = mid - 1;
  }
  return nullptr;
}

// Decode one UTF-8 character and advance pointer
inline uint16_t utf8ToUnicode(const char **p) {
  uint8_t b0 = (uint8_t)(*p)[0];
  if (b0 < 0x80) { (*p)++; return b0; }
  if ((b0 & 0xE0) == 0xC0) {
    uint16_t c = ((uint16_t)(b0 & 0x1F) << 6) | ((uint8_t)(*p)[1] & 0x3F);
    (*p) += 2; return c;
  }
  if ((b0 & 0xF0) == 0xE0) {
    uint16_t c = ((uint16_t)(b0 & 0x0F) << 12)
               | ((uint16_t)((*p)[1] & 0x3F) << 6)
               | ((*p)[2] & 0x3F);
    (*p) += 3; return c;
  }
  (*p) += 4; return 0;
}

// Draw GB2312 text at (x, y) using the 16px dot-matrix font.
// Each CJK character is 16px wide. ASCII chars are 8px wide.
// Line breaks at '\n'.
inline void drawGB16(int x, int y, const char *text, uint16_t fg, uint16_t bg) {
  int origX = x;
  while (*text) {
    if (*text == '\n') { x = origX; y += 20; text++; continue; }
    uint16_t uc = utf8ToUnicode(&text);
    if (uc < 0x80) {
      tft->setTextSize(1);
      tft->setTextColor(fg, bg);
      tft->setCursor(x, y + 4);
      tft->print((char)uc);
      x += 8;
      continue;
    }
    if (uc < 0x4E00 || uc > 0x9FFF) { // skip non-CJK
      if (uc >= 0x3000 && uc <= 0x303F) {} // CJK symbols, allow through
      else if (uc >= 0xFF00 && uc <= 0xFFEF) {} // fullwidth forms, allow through
      else if (uc >= 0x2000 && uc <= 0x206F) {} // general punctuation, allow through
      else if (uc >= 0x2100 && uc <= 0x214F) {} // letterlike symbols, allow through
      else if (uc >= 0xFE30 && uc <= 0xFE4F) {} // CJK compatibility forms, allow through
      else continue;
    }
    const uint8_t *g = findGB2312Glyph(uc);
    if (!g) { x += 16; continue; }
    for (int row = 0; row < 16; row++) {
      uint16_t bits = ((uint16_t)pgm_read_byte(&g[row * 2]) << 8) | pgm_read_byte(&g[row * 2 + 1]);
      for (int col = 0; col < 16; col++) {
        if (bits & (0x8000 >> col)) {
          tft->drawPixel(x + col, y + row, fg);
        }
      }
    }
    x += 16;
  }
}
